import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useTreeStore } from "@/hooks/useTreeStore";
import { TreeService } from "@/services/TreeService";
import { ApiError } from "@/services/api";
import { Tree } from "@/types/tree";
import { DuplicatePair } from "@/types/merge";
import {
  PairResolutionState,
  buildInitialResolutionState,
  memberDisplayName,
} from "@/utils/mergeUtils";
import { MergeConflictResolver } from "@/components/view/database-management-view/dialog/MergeConflictResolver";

type Mode = "existing" | "create";

interface Props {
  /** Id of the tree the member being linked currently lives in (the source
   *  side of the bridge, "A" in every conflict). */
  sourceTreeId: string;
  memberId: string;
  memberName: string;
  tree: Tree;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onLinked: () => void;
}

/**
 * Resolves a tree-in-tree bridge person against an already-existing target
 * tree, opened from `LinkedTreeField` when the user picks a tree from the
 * dropdown. The member must already be saved (bridging writes rows in two
 * trees) and the caller must have write access to the target — both are
 * enforced by the backend, but the no-access case is also short-circuited
 * here from `tree.role` for a friendlier state.
 *
 * In "find existing person" mode, only same-named candidates from the
 * merge/duplicate-detection machinery are offered (#565 follow-up) — picking
 * one that conflicts on some fields opens the same `MergeConflictResolver`
 * used by tree merge, so differences are resolved instead of left to drift.
 */
export const LinkExistingTreeDialog = ({
  sourceTreeId,
  memberId,
  memberName,
  tree,
  open,
  onOpenChange,
  onLinked,
}: Props) => {
  const { t } = useTranslation(undefined, {
    keyPrefix: "sheet.edit-mode.linked-tree.link-dialog",
  });
  const linkExistingTree = useTreeStore((s) => s.linkExistingTree);

  const [mode, setMode] = useState<Mode>("existing");
  const [candidates, setCandidates] = useState<DuplicatePair[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [resolutionState, setResolutionState] =
    useState<PairResolutionState | null>(null);
  const [submitting, setSubmitting] = useState(false);

  const hasWriteAccess = tree.role === "owner" || tree.role === "editor";

  useEffect(() => {
    if (!open || !hasWriteAccess) return;
    setMode("existing");
    setSelectedId(null);
    setResolutionState(null);
    setLoading(true);
    TreeService.getLinkCandidates(sourceTreeId, memberId, tree.id)
      .then((res) => setCandidates(res.candidates))
      .catch(() => setCandidates([]))
      .finally(() => setLoading(false));
  }, [open, hasWriteAccess, sourceTreeId, memberId, tree.id]);

  const selectedPair =
    candidates.find((c) => c.member_b.id === selectedId) ?? null;

  const handleSelectCandidate = (id: string) => {
    setSelectedId(id);
    const pair = candidates.find((c) => c.member_b.id === id);
    setResolutionState(pair ? buildInitialResolutionState(pair) : null);
  };

  const handleConfirm = async () => {
    setSubmitting(true);
    try {
      await linkExistingTree(memberId, {
        linked_tree_id: tree.id,
        mode,
        counterpart_member_id: mode === "existing" ? selectedId : undefined,
        field_choices:
          mode === "existing" && resolutionState
            ? resolutionState.fields
            : undefined,
      });
      toast.success(t("toast-success", { name: tree.name }));
      onLinked();
      onOpenChange(false);
    } catch (err) {
      if (err instanceof ApiError && err.status === 409) {
        toast.error(t("toast-error-already-linked"));
      } else if (err instanceof ApiError && err.status === 403) {
        toast.error(t("toast-error-no-access"));
      } else {
        toast.error(t("toast-error-generic"));
      }
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-2xl">
        <DialogHeader>
          <DialogTitle>{t("title", { name: tree.name })}</DialogTitle>
          <DialogDescription>
            {t("description", { member: memberName, tree: tree.name })}
          </DialogDescription>
        </DialogHeader>

        {!hasWriteAccess ? (
          <p className="text-sm text-muted-foreground">
            {t("no-access", { tree: tree.name })}
          </p>
        ) : (
          <Tabs value={mode} onValueChange={(v) => setMode(v as Mode)}>
            <TabsList className="w-full">
              <TabsTrigger value="existing" className="flex-1">
                {t("mode-existing")}
              </TabsTrigger>
              <TabsTrigger value="create" className="flex-1">
                {t("mode-create")}
              </TabsTrigger>
            </TabsList>
            <TabsContent value="existing" className="space-y-2">
              <p className="text-xs text-muted-foreground">
                {t("mode-existing-description")}
              </p>
              {!loading && candidates.length === 0 ? (
                <p className="text-sm text-muted-foreground">
                  {t("no-candidates", { member: memberName, tree: tree.name })}
                </p>
              ) : (
                <Select
                  value={selectedId ?? undefined}
                  onValueChange={handleSelectCandidate}
                  disabled={loading}
                >
                  <SelectTrigger className="w-full">
                    <SelectValue
                      placeholder={
                        loading ? t("loading") : t("existing-placeholder")
                      }
                    />
                  </SelectTrigger>
                  <SelectContent>
                    {candidates.map((c) => (
                      <SelectItem key={c.member_b.id} value={c.member_b.id}>
                        {memberDisplayName(c.member_b)}
                        {c.member_b.dateOfBirth
                          ? ` (${c.member_b.dateOfBirth})`
                          : ""}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              )}

              {selectedPair && selectedPair.conflicts.length > 0 && (
                <div className="pt-2">
                  <MergeConflictResolver
                    pair={selectedPair}
                    sourceAName={memberName}
                    sourceBName={tree.name}
                    state={
                      resolutionState ??
                      buildInitialResolutionState(selectedPair)
                    }
                    onChange={(updated) =>
                      setResolutionState({ ...updated, action: "merge" })
                    }
                  />
                </div>
              )}
            </TabsContent>
            <TabsContent value="create" className="space-y-2">
              <p className="text-xs text-muted-foreground">
                {t("mode-create-description", {
                  member: memberName,
                  tree: tree.name,
                })}
              </p>
            </TabsContent>
          </Tabs>
        )}

        <DialogFooter>
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={() => onOpenChange(false)}
          >
            {t("cancel")}
          </Button>
          {hasWriteAccess && (
            <Button
              type="button"
              size="sm"
              disabled={
                submitting ||
                (mode === "existing" &&
                  (selectedId === null || candidates.length === 0))
              }
              onClick={() => void handleConfirm()}
            >
              {t("confirm")}
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

/**
 * Pure helper functions for the merge conflict-resolution UI (#166).
 *
 * Kept in a standalone module so they can be unit-tested without DOM or
 * network dependencies.
 */

import { MemberDB } from "@/types/member";
import {
  DuplicatePair,
  MergeFieldChoice,
  MergeResolution,
} from "@/types/merge";

/**
 * Fields that can be chosen / combined when resolving merge conflicts.
 * Mirrors the backend's _CONFLICT_FIELDS list.
 */
export const RESOLVABLE_FIELDS: readonly string[] = [
  "middleNames",
  "baptismalName",
  "maidenName",
  "birthplace",
  "hometown",
  "cemetery",
  "placesLived",
  "additionalData",
  "imageData",
  "dateOfBirth",
  "dateOfDeath",
];

/**
 * Fields for which the "Combine" option makes sense (free-form text).
 */
export const COMBINABLE_FIELDS: readonly string[] = [
  "additionalData",
  "placesLived",
];

/**
 * Per-pair UI state that the user fills in during the resolve step.
 */
export interface PairResolutionState {
  action: "merge" | "keep_both";
  /** Only relevant when action === "merge". */
  fields: Partial<Record<string, MergeFieldChoice>>;
}

/**
 * Build the initial resolution state for a duplicate pair from the backend's
 * `default_action` suggestion and its conflict list.
 */
export function buildInitialResolutionState(
  pair: DuplicatePair,
): PairResolutionState {
  const fields: Partial<Record<string, MergeFieldChoice>> = {};
  for (const field of pair.conflicts) {
    // Default field choice: "a" (keep source-A value)
    fields[field] = "a";
  }
  return {
    action: pair.default_action,
    fields,
  };
}

/**
 * Convert the map of per-pair UI state into the `resolutions` array expected
 * by POST /trees/merge.
 *
 * Only pairs that are not using the server default need a resolution entry,
 * but we send all to keep the logic simple.
 */
export function buildResolutionsPayload(
  pairs: DuplicatePair[],
  states: Map<string, PairResolutionState>,
): MergeResolution[] {
  return pairs.map((pair) => {
    const pairKey = buildPairKey(pair.member_a.id, pair.member_b.id);
    const state = states.get(pairKey) ?? buildInitialResolutionState(pair);
    return {
      member_a_id: pair.member_a.id,
      member_b_id: pair.member_b.id,
      action: state.action,
      fields: state.action === "merge" ? { ...state.fields } : {},
    };
  });
}

/**
 * A stable string key for a pair that is order-insensitive.
 */
export function buildPairKey(idA: string, idB: string): string {
  return [idA, idB].sort().join("|");
}

/**
 * Human-readable display label for a member (first + last name).
 */
export function memberDisplayName(m: MemberDB): string {
  return [m.firstName, m.lastName].filter(Boolean).join(" ") || "(unknown)";
}

/**
 * Return the value of a named field from a MemberDB record.
 */
export function getMemberField(
  member: MemberDB,
  field: string,
): string | null | undefined {
  return (member as unknown as Record<string, unknown>)[field] as
    | string
    | null
    | undefined;
}

/**
 * Return true when both member values are non-empty and differ.
 * Used to decide whether to show a highlighted conflict badge.
 */
export function isFieldConflicting(
  pair: DuplicatePair,
  field: string,
): boolean {
  return pair.conflicts.includes(field);
}

