import { type Member, type MemberDB } from "@/types/member";
import { type DuplicatePair, type MemberMergePreview } from "@/types/merge";
import { MergeMembersDialog } from "./MergeMembersDialog";

// Radix Select relies on scrollIntoView / hasPointerCapture, which jsdom
// doesn't implement.
class MockResizeObserver {
  observe() {}
  unobserve() {}
  disconnect() {}
}
// @ts-expect-error -- test-only polyfill
global.ResizeObserver = MockResizeObserver;

vi.mock("@/services/TreeService", () => ({
  TreeService: {
    getMemberMergePreview: vi.fn(),
  },
}));

vi.mock("sonner", () => ({
  toast: {
    error: vi.fn(),
    success: vi.fn(),
  },
}));

function makeAppMember(overrides: Partial<Member> = {}): Member {
  return {
    id: "a1",
    gender: "f",
    academicTitle: null,
    firstName: "Jo",
    middleNames: null,
    baptismalName: null,
    lastName: "Doe",
    maidenName: null,
    imageData: null,
    deceased: false,
    adopted: false,
    date: { birth: "", death: null },
    parents: { paternalParent: null, maternalParent: null },
    additionalData: null,
    birthplace: null,
    hometown: null,
    cemetery: null,
    placesLived: [],
    isCollapsed: false,
    position: { x: 0, y: 0 },
    ...overrides,
  };
}

const MEMBER_A: MemberDB = {
  id: "a1",
  gender: "f",
  academicTitle: null,
  firstName: "Jo",
  middleNames: null,
  baptismalName: null,
  lastName: "Doe",
  maidenName: null,
  imageData: null,
  dateOfBirth: null,
  dateOfDeath: null,
  deceased: false,
  adopted: false,
  isCollapsed: 0,
  positionX: 0,
  positionY: 0,
  linkedTreeId: null,
  linkedMemberId: null,
};

function memberB(overrides: Partial<MemberDB>): MemberDB {
  return { ...MEMBER_A, id: "b1", ...overrides };
}

function pair(overrides: Partial<DuplicatePair>): DuplicatePair {
  return {
    member_a: MEMBER_A,
    member_b: memberB({}),
    match: "exact",
    conflicts: [],
    default_action: "merge",
    ...overrides,
  };
}

function preview(overrides: Partial<MemberMergePreview>): MemberMergePreview {
  return {
    pair: pair({}),
